-- ==============================================================================
-- seed-comprehensive-exercises.sql
-- Run in Supabase SQL Editor (Dashboard > SQL Editor) to populate all 135
-- training exercises across all muscle groups, equipment, and unilateral movements.
-- All exercises are fully ranked with canonical standard key mapping.
-- ==============================================================================

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  muscle_group = EXCLUDED.muscle_group,
  equipment = EXCLUDED.equipment,
  is_compound = EXCLUDED.is_compound,
  is_ranked = EXCLUDED.is_ranked,
  ranked_key = EXCLUDED.ranked_key;
